let explored=new Set(s.explored),route=[],selected=null,task=null,placement=null,keys=new Set(),particles=[],anim=0,stepClock=0,uiClock=0,saveClock=0,last=performance.now(),toastTimer,face=1,moving=false,cam={x:s.player.x*C.T,y:s.player.y*C.T},view={w:470,h:900},sheetType='',focusBefore=null;
