const assets={},P='Units/Blue Units/Pawn/',TREE='Terrain/Resources/Wood/Trees/Tree1.png',STUMP='Terrain/Resources/Wood/Trees/Stump 1.png',ROCK='Terrain/Decorations/Rocks/Rock1.png',SHEEP='Terrain/Resources/Meat/Sheep/',FIRE='Particle FX/Fire_01.png';
