function save(){s.last=Date.now();s.explored=[...explored];try{localStorage.setItem(KEY,JSON.stringify(s))}catch{toast('Сохранение недоступно: проверьте настройки браузера.')}}
function fmt(seconds){seconds=Math.max(0,Math.ceil(seconds));return seconds>=60?`${Math.floor(seconds/60)} м ${seconds%60} с`:`${seconds} с`}
function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
const audio={ctx:null,master:null,music:null,fx:null,ambient:null,timer:null,note:0,
 start(){if(!this.ctx){this.ctx=new(window.AudioContext||window.webkitAudioContext)();this.master=this.ctx.createGain();this.master.connect(this.ctx.destination);this.fx=this.ctx.createGain();this.fx.connect(this.master);this.music=this.ctx.createGain();this.music.connect(this.master);let buffer=this.ctx.createBuffer(1,this.ctx.sampleRate*3,this.ctx.sampleRate),data=buffer.getChannelData(0),v=0;for(let i=0;i<data.length;i++){v=(v+(Math.random()*2-1)*.03)/1.025;data[i]=v}let src=this.ctx.createBufferSource(),filter=this.ctx.createBiquadFilter();src.buffer=buffer;src.loop=true;filter.type='lowpass';filter.frequency.value=480;this.ambient=this.ctx.createGain();this.ambient.gain.value=.12;src.connect(filter).connect(this.ambient).connect(this.fx);src.start();this.timer=setInterval(()=>this.tick(),650)}this.ctx.resume();this.update()},
 update(){if(!this.ctx)return;this.master.gain.setTargetAtTime(s.audio.enabled&&!document.hidden?1:0,this.ctx.currentTime,.15);this.music.gain.value=s.audio.music;this.fx.gain.value=s.audio.effects;$('#audio').textContent=s.audio.enabled?'♫':'♪'},
 tone(f,d=.2,v=.1,type='triangle',delay=0,dest='fx',end=null){if(!this.ctx||!s.audio.enabled||document.hidden)return;let o=this.ctx.createOscillator(),g=this.ctx.createGain(),t=this.ctx.currentTime+delay;o.type=type;o.frequency.setValueAtTime(f,t);if(end)o.frequency.exponentialRampToValueAtTime(end,t+d);g.gain.setValueAtTime(.0001,t);g.gain.linearRampToValueAtTime(v,t+.012);g.gain.exponentialRampToValueAtTime(.0001,t+d);o.connect(g).connect(this[dest]);o.start(t);o.stop(t+d+.02)},
 noise(d=.15,v=.2,f=800,delay=0){if(!this.ctx||!s.audio.enabled||document.hidden)return;let b=this.ctx.createBuffer(1,Math.ceil(this.ctx.sampleRate*d),this.ctx.sampleRate),a=b.getChannelData(0);for(let i=0;i<a.length;i++)a[i]=(Math.random()*2-1);let src=this.ctx.createBufferSource(),g=this.ctx.createGain(),filter=this.ctx.createBiquadFilter(),t=this.ctx.currentTime+delay;src.buffer=b;filter.type='lowpass';filter.frequency.value=f;g.gain.setValueAtTime(v,t);g.gain.exponentialRampToValueAtTime(.0001,t+d);src.connect(filter).connect(g).connect(this.fx);src.start(t);src.stop(t+d)},
 play(name){switch(name){case'clash':this.noise(.09,.17,2600);this.tone(720,.1,.07,'triangle',0,'fx',210);break;case'bow':this.noise(.11,.12,3200);this.tone(420,.08,.055,'triangle',0,'fx',170);break;case'heal':this.tone(523,.24,.06);this.tone(784,.3,.04,'sine',.12);break;case'fireCrackle':this.noise(.08,.05,1800);break;case'horn':this.tone(294,.3,.08,'triangle');this.tone(392,.5,.08,'triangle',.2);break;case'plant':this.noise(.22,.15,650);this.tone(330,.12,.04);break;case'sizzle':this.noise(.65,.15,3400);break;case'click':this.tone(660,.07,.07);break;case'step':this.noise(.075,.09,450+Math.random()*300);this.tone(95,.06,.025,'sine');break;case'chop':this.noise(.1,.45,1600);this.tone(150,.14,.16,'triangle',0,'fx',65);break;case'rock':this.tone(1100,.17,.15,'triangle');this.noise(.07,.2,3800);break;case'fall':this.noise(.9,.35,600);this.tone(100,.65,.12,'sawtooth',0,'fx',35);break;case'collect':[523,659,784].forEach((n,i)=>this.tone(n,.2,.06,'triangle',i*.07));break;case'place':this.noise(.12,.2,900);this.tone(240,.14,.12);break;case'hammer':this.noise(.06,.25,2500);this.tone(380,.1,.08);break;case'splash':this.noise(.6,.23,4500);this.tone(420,.18,.09,'sine',0,'fx',110);break;case'cast':this.noise(.18,.12,2500);this.noise(.25,.18,3500,.2);break;case'bleat':this.tone(240,.38,.07,'sawtooth',0,'fx',180);this.tone(280,.25,.035,'triangle',.12,'fx',180);break;case'hunt':this.noise(.15,.18,1800);this.play('bleat');break;case'eat':this.noise(.12,.15,1200);this.noise(.1,.12,900,.15);this.tone(500,.2,.06,'triangle',.25);break;case'complete':[392,493.88,587.33,783.99].forEach((n,i)=>this.tone(n,.5,.09,'triangle',i*.14));break;case'destroy':this.noise(.7,.32,900);break;}},
 tick(){if(!this.ctx||!s.started||document.hidden||!s.audio.enabled)return;const melody=[392,0,493.88,587.33,0,493.88,440,0,349.23,0,440,523.25,0,440,392,0,329.63,392,493.88,0,440,392,329.63,0,293.66,0,349.23,440,392,0,293.66,0];let n=melody[this.note%melody.length];if(n)this.tone(n,1.5,.045,'sine',0,'music');if(this.note%8===0){let bass=[196,174.61,164.81,146.83][Math.floor(this.note/8)%4];this.tone(bass,4,.035,'triangle',0,'music');this.tone(bass*1.5,3,.018,'sine',0,'music')}if(this.note%13===0&&Military.daylight(s.time).night<.5){this.tone(1600,.18,.035,'sine',0,'fx',2200);this.tone(2100,.14,.025,'sine',.2,'fx',1600)}if(this.note%4===0&&Military.daylight(s.time).night>.5){this.tone(3100,.06,.014,'sine');this.tone(3400,.07,.012,'sine',.12)}if(this.note%3===0&&s.buildings.some(b=>(b.type==='fire'&&C.ready(b)||b.burningUntil>s.time)&&dist(s.player,{x:b.x+.5,y:b.y+.5})<5))this.play('fireCrackle');let riverDistance=Math.abs(s.player.x-C.riverX(s.player.y));this.ambient.gain.setTargetAtTime(riverDistance<5?.35:.10,this.ctx.currentTime,.5);if(this.note%17===0&&s.sheep.some(a=>a.hp>0&&dist(a,s.player)<5))this.play('bleat');this.note++}
};
function reveal(){for(let c of C.territories(s).slice(1))for(let yy=c.y;yy<c.y+c.h;yy++)for(let xx=c.x;xx<c.x+c.w;xx++)explored.add(xx+','+yy);let x=Math.floor(s.player.x),y=Math.floor(s.player.y);for(let dy=-5;dy<=5;dy++)for(let dx=-5;dx<=5;dx++)if(dx*dx+dy*dy<30)explored.add(`${x+dx},${y+dy}`);for(let b of s.buildings)if(b.type==='tower'&&C.ready(b))for(let dy=-7;dy<=7;dy++)for(let dx=-7;dx<=7;dx++)if(dx*dx+dy*dy<50)explored.add(`${b.x+dx},${b.y+dy}`)}
function targetPoint(t){if(t.kind==='building'){let r=C.recipes[t.ref.type];return{x:t.ref.x+r.w/2,y:t.ref.y+r.h/2}}return{x:t.ref.x+.5,y:t.ref.y+.5}}
function nearTarget(t){if(!t)return false;return dist(s.player,targetPoint(t))<(t.kind==='building'?2.5:1.8)}
function nearest(){let choices=[];for(let n of s.nodes)if(n.hp>0&&dist(s.player,{x:n.x+.5,y:n.y+.5})<2.3)choices.push({kind:n.kind,ref:n});for(let a of s.sheep)if(a.hp>0&&!a.penTarget&&dist(s.player,{x:a.x+.5,y:a.y+.5})<2.3)choices.push({kind:'sheep',ref:a});let px=Math.floor(s.player.x),py=Math.floor(s.player.y);for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)if(C.water(px+dx,py+dy))choices.push({kind:'water',ref:{x:px+dx,y:py+dy}});choices.sort((a,b)=>dist(s.player,targetPoint(a))-dist(s.player,targetPoint(b)));return choices[0]||null}
function currentTarget(){if(selected){if(['tree','rock','berry','sheep'].includes(selected.kind)&&(selected.ref.hp<=0||selected.ref.penTarget))selected=null;else return selected}return nearest()}
function moveTo(x,y){battleView=false;task=null;let p=C.path(s,s.player.x,s.player.y,x,y);if(!p.length&&Math.hypot(Math.floor(s.player.x)-x,Math.floor(s.player.y)-y)>.1){toast('Проход закрыт. Расчистите путь или обойдите.');return false}route=p;return true}
function approach(t){let p=targetPoint(t),opts=[];let range=t.kind==='building'?3:1;for(let y=Math.floor(p.y)-range;y<=Math.floor(p.y)+range;y++)for(let x=Math.floor(p.x)-range;x<=Math.floor(p.x)+range;x++)if(C.walkable(s,x,y)&&dist({x:x+.5,y:y+.5},p)<(t.kind==='building'?2.5:1.8)){let path=C.path(s,s.player.x,s.player.y,x,y);if(path.length||Math.floor(s.player.x)===x&&Math.floor(s.player.y)===y)opts.push({path,len:path.length})}opts.sort((a,b)=>a.len-b.len);if(!opts.length){toast('Сначала расчистите подход к этому месту.');return false}task=null;route=opts[0].path;selected=t;return true}
function addParticles(x,y,color,count=10){for(let i=0;i<count;i++)particles.push({x:x*C.T,y:y*C.T,vx:(Math.random()-.5)*75,vy:-20-Math.random()*65,life:.7+Math.random()*.5,color})}
function beginAction(){if(task||placement)return;let t=currentTarget();if(!t){toast('Нажмите на дерево, камень или овцу. Исследуйте берега реки.');return}if(!nearTarget(t)){approach(t);toast('Подойдите ближе, затем нажмите действие.');return}route=[];if(t.kind==='camp'){showCamp();return}if(t.kind==='landmark'){showLandmark(t.ref);return}if(t.kind==='building'){showBuilding(t.ref);return}if(t.kind==='water'&&!s.rod){toast('Нужна удочка: постройте дом, затем изготовьте её в рюкзаке.');return}if(s.energy<(t.kind==='sheep'||t.kind==='water'?4:3)){toast('Поешьте или немного отдохните. Силы восстанавливаются сами.');return}const durations={tree:s.axe>1?1.7:3,rock:3.5,berry:2,sheep:2,water:s.rodLevel===2?6:9};task={kind:t.kind,target:t.ref,start:s.time,end:s.time+durations[t.kind],hits:0};selected=t;face=targetPoint(t).x>=s.player.x?1:-1;if(t.kind==='water')audio.play('cast');else audio.play(t.kind==='tree'?'chop':t.kind==='rock'?'rock':t.kind==='sheep'?'hunt':'collect');renderHUD()}
function completeTask(){let t=task;if(!t)return;let result;if(t.kind==='ore'){economyResult(Economy.discover(s,t.target.id));task=null;save();renderHUD();return}if(t.kind==='water'){if(!s.rod||!nearTarget({kind:'water',ref:t.target})){task=null;return}s.fish++;s.stats.fish++;s.energy=Math.max(0,s.energy-4);s.xp+=5;result={kind:'fish',amount:1};audio.play('splash');if(s.stats.fish===1)log('Первая рыба! Река станет надёжным источником еды.')}else if(t.kind==='sheep'){result=C.hunt(s,t.target.id);if(result?.kind==='meat')log('Охота принесла 3 порции мяса.')}else result=C.harvest(s,t.target.id);if(result?.error)toast(result.error);else if(result){if(result.amount){float(`+${result.amount} ${symbols[result.kind]}`);audio.play('collect')}addParticles(t.target.x+.5,t.target.y+.5,t.kind==='tree'?'#e4cb86':'#ded9b1');if(result.finished){audio.play('fall');if(t.kind==='tree'&&s.stats.trees===1)log('Первое дерево срублено. Из 30 единиц древесины можно построить дом.')}if(result.kind==='hit')toast('Ещё один удар — и мясо ваше.')}task=null;if(result&&!result.error&&['tree','rock','sheep'].includes(t.kind)&&t.target.hp>0){if(s.energy>=(t.kind==='sheep'?4:3))beginAction();else toast('Работа остановлена: поешьте или отдохните.')}save();renderHUD()}
function renderHUD(){renderWorkerDashboard();renderStructureStatus();renderCombatStatus();renderEconomyStatus();for(let el of document.querySelectorAll('[data-training]')){let b=s.buildings.find(b=>b.id===el.dataset.training);if(b)el.innerHTML=trainingStatus(b)}for(let el of document.querySelectorAll('[data-worker-need]')){let w=s.workers.find(w=>w.id===el.dataset.workerNeed);if(w)el.value=w[el.dataset.need]}for(let el of document.querySelectorAll('[data-worker-status]')){let w=s.workers.find(w=>w.id===el.dataset.workerStatus);if(w)el.textContent=Workers.roles[w.role]+' · '+w.status}for(let el of document.querySelectorAll('[data-cook-timer]')){let fire=s.buildings.find(b=>b.id===el.dataset.cookTimer);el.textContent=fire?.cooking?(fire.ruined?'Приостановлено':fmt(fire.cooking.end-s.time)):'Готово! Еда в рюкзаке.'}$('#energy').value=s.energy;$('#energyValue').textContent=Math.floor(s.energy);let light=Military.daylight(s.time);$('#day').textContent=`${light.icon} ${light.name} ${1+Math.floor(s.time/Military.DAY_SECONDS)} · ${fmt(light.phaseRemaining)} до ${light.nextPhase}`;let nearRiver=Math.abs(s.player.x-C.riverX(s.player.y))<4;$('#region').textContent=nearRiver?'Шелестящая река':C.owned(s,s.player.x,s.player.y)?'Ваша территория':'Неизведанный лес';let t=currentTarget(),info={tree:['Лесное дерево','Одно нажатие — рубим до конца. Можно остановить.','🪓','Рубить',s.axe>1?'1,7 с':'3 с'],rock:['Каменная россыпь','Камень пригодится для костра, мастерской и башни.','⛏','Добывать','3,5 с'],berry:['Лесные ягоды','Небольшой перекус в дороге.','🫐','Собрать','2 с'],sheep:['Лесная овца','Одна охота даёт 3 порции сырого мяса. Приготовьте на костре.','⚔','Охотиться','2 с'],water:['Шелестящая река',s.rod?'Спокойная вода. Хорошее место для рыбалки.':'Изготовьте удочку в рюкзаке после постройки дома.','🐟',s.rod?'Ловить рыбу':'Нужна удочка',s.rodLevel===2?'6 с':'9 с'],camp:['Лагерь разбойников',campStatus(),'⚔','Осмотреть',''],landmark:t?.kind==='landmark'?[t.ref.name,landmarkStatus(t.ref),'✧','Осмотреть','']:null,building:t?.kind==='building'?[C.recipes[t.ref.type].name,t.ref.end?'Строится: '+fmt(t.ref.end-s.time):'Ваша постройка. Можно осмотреть или снести.','⌂','Осмотреть','']:null};let a=t?info[t.kind]:['Ваша история начинается здесь','Нажмите на землю, чтобы идти. На дерево — чтобы выбрать.','✧','Исследовать',''];$('#targetName').textContent=a[0];$('#targetHint').textContent=route.length?'Идём к выбранному месту…':a[1];$('#actionIcon').textContent=a[2];$('#actionText').textContent=task?'В процессе…':t&&!nearTarget(t)?'Подойти':a[3];$('#actionTime').textContent=a[4];$('#act').disabled=!!task||!t||t.kind==='water'&&!s.rod;$('#taskProgress').hidden=!task;$('#cancelTask').hidden=!task;if(task){$('#taskFill').style.width=`${Math.min(100,(s.time-task.start)/(task.end-task.start)*100)}%`;$('#taskLabel').textContent=`${task.kind==='ore'?'Добываем руду':a[3]} · ${fmt(task.end-s.time)}`}$('#eat').disabled=s.cookedMeat+s.cookedFish+s.berries+s.vegetables+s.cookedVegetables===0||s.energy>=99;}
function openSheet(title,kicker,html,type=''){$('#armyBar').hidden=true;armyAttackMode=false;armyPlacement=false;$('#orderHint').hidden=true;task=null;route=[];keys.clear();sheetType=type;focusBefore=document.activeElement;$('#sheetTitle').textContent=title;$('#sheetKicker').textContent=kicker;$('#sheetBody').innerHTML=html;$('#sheet').hidden=false;$('#sheetBackdrop').hidden=false;$('#closeSheet').focus();audio.play('click')}
function closeSheet(){sheetType='';$('#sheet').hidden=true;$('#sheetBackdrop').hidden=true;focusBefore?.focus?.();audio.play('click')}
function showBuild(){openSheet('Постройте своё место','ОДНА ДОСКА ЗА ДРУГОЙ',`<p>Выберите постройку, затем место на своей земле. Деревья сначала нужно срубить.</p><div class="cards">${Object.entries(C.recipes).map(([k,r])=>`<button class="card ${C.level(s)<r.unlock?'locked':''}" data-build="${k}" ${C.level(s)<r.unlock?'disabled':''}><span>${r.icon}</span><b>${r.name}</b><small>${r.desc}</small><div class="cost">${r.wood} 🪵 ${r.stone?r.stone+' 🪨':''} · ${fmt(r.seconds)}${C.level(s)<r.unlock?'<br>🔒 '+(r.unlock===2?'Нужна мастерская':'Нужен дом'):''}</div></button>`).join('')}</div>`,'build')}

let workerSelection=new Set(),workerFilter='all',workerFocus=null;
function workerNeedsHelp(w){return w.hunger<25||w.thirst<25||w.energy<15||/Нет|Нуж|Ждёт/.test(w.status||'')}
function showWorkers(){let scroll=sheetType==='workers'?$('#sheet').scrollTop:0;workerSelection=new Set([...workerSelection].filter(id=>s.workers.some(w=>w.id===id)));openSheet('Рабочие','ПОСЕЛЕНИЕ',`<div class="workers-summary" id="workerSummary"></div><button class="gold wide" data-do="hire" ${s.workers.length>=Workers.capacity(s)||Military.food(s)<3?'disabled':''}>Пригласить рабочего · 3 еды</button><div class="worker-command"><div class="worker-tools"><button data-worker-select="all">Выбрать всех</button><button data-worker-select="idle">Свободные</button><button data-worker-select="none">Снять выбор</button></div><b id="workerSelectionCount"></b><div class="worker-batch">${Object.entries(Workers.roles).map(([key,label])=>`<button data-worker-batch="${key}">${label}<small data-role-count="${key}"></small></button>`).join('')}</div></div><label class="worker-filter">Показать <select id="workerFilter" aria-label="Фильтр рабочих"><option value="all" ${workerFilter==='all'?'selected':''}>Всех жителей</option><option value="help" ${workerFilter==='help'?'selected':''}>Нужна помощь</option></select></label><div id="workerList">${s.workers.map(w=>`<article class="worker-card compact-worker" data-worker-row="${w.id}"><div class="worker-heading"><label><input type="checkbox" data-worker-select-id="${w.id}" aria-label="Выбрать: ${w.name}" ${workerSelection.has(w.id)?'checked':''}><b>${w.name}</b></label><button data-worker-find="${w.id}" aria-label="Найти: ${w.name}">Найти</button></div><small data-worker-status="${w.id}">${Workers.roles[w.role]} · ${w.status}</small><div class="worker-needs">${[['energy','Силы'],['hunger','Еда'],['thirst','Вода']].map(([key,label])=>`<label>${label}<progress max="100" value="${w[key]}" data-worker-need="${w.id}" data-need="${key}" aria-label="${w.name}: ${label}"></progress></label>`).join('')}</div><label class="worker-job">Работа<select data-worker-job="${w.id}" aria-label="Работа: ${w.name}">${Object.entries(Workers.roles).map(([key,label])=>`<option value="${key}" ${w.role===key?'selected':''}>${label}</option>`).join('')}</select></label></article>`).join('')}</div><p>Выбери жителей и назначь работу группе, либо измени профессию в карточке. Сон, еда и вода — автоматически. Строители ускоряют оплаченный ремонт.</p>`,'workers');$('#sheet').scrollTop=scroll||0;renderWorkerDashboard()}
function renderWorkerDashboard(){if(sheetType!=='workers')return;$('#workerSummary').textContent='Жители: '+s.workers.length+' / '+Workers.capacity(s)+' · Готовая еда: '+Military.food(s);$('#workerSelectionCount').textContent='Выбрано: '+workerSelection.size;for(let el of document.querySelectorAll('[data-worker-select-id]'))el.checked=workerSelection.has(el.dataset.workerSelectId);for(let el of document.querySelectorAll('[data-worker-batch]'))el.disabled=!workerSelection.size;for(let el of document.querySelectorAll('[data-role-count]'))el.textContent=s.workers.filter(w=>w.role===el.dataset.roleCount).length+' чел.';for(let el of document.querySelectorAll('[data-worker-row]')){let w=s.workers.find(w=>w.id===el.dataset.workerRow);el.hidden=workerFilter==='help'&&!workerNeedsHelp(w)}for(let el of document.querySelectorAll('[data-worker-job]')){let w=s.workers.find(w=>w.id===el.dataset.workerJob);if(w&&el.value!==w.role)el.value=w.role}}
function workerClick(button){let data=button.dataset;if(data.workerSelect){workerSelection=new Set(data.workerSelect==='none'?[]:s.workers.filter(w=>data.workerSelect==='all'||w.role==='idle').map(w=>w.id));renderWorkerDashboard();audio.play('click');return true}if(data.workerBatch){let result=Workers.assignMany(s,[...workerSelection],data.workerBatch);economyResult(result);renderWorkerDashboard();return true}if(data.workerFind){workerFocus=data.workerFind;battleView=false;route=[];task=null;closeSheet();let w=s.workers.find(w=>w.id===workerFocus);if(w){cam.x=w.x*C.T;cam.y=w.y*C.T;toast('Камера: '+w.name+'. «Домой» — вернуться к персонажу.')}return true}return false}
function workerChange(e){let el=e.target;if(el.dataset.workerSelectId){if(el.checked)workerSelection.add(el.dataset.workerSelectId);else workerSelection.delete(el.dataset.workerSelectId);renderWorkerDashboard();return}if(el.dataset.workerJob){Workers.assign(s,el.dataset.workerJob,el.value);audio.play('click');save();renderHUD();return}if(el.id==='workerFilter'){workerFilter=el.value;renderWorkerDashboard()}}
function buildingCondition(b){C.buildingState(b);return (b.ruined?'Разрушено':b.burningUntil>s.time?'Горит':b.hp<b.maxHp?'Повреждено':'Исправно')+' · '+Math.ceil(b.hp)+' / '+b.maxHp+' прочности'+(b.repair?' · '+(b.repair.blocked?'Освободите участок для восстановления':'Ремонт: '+fmt(b.repair.remaining)):'')}
function structurePanel(b){let cost=C.repairCost(b);return `<div class="info-box" data-structure-status="${b.id}">${buildingCondition(b)}</div><button class="gold wide" data-repair="${b.id}" ${b.repair||b.hp>=b.maxHp||s.wood<cost.wood||s.stone<cost.stone?'disabled':''}>${b.ruined?'Восстановить':'Починить'} · ${cost.wood} дерева · ${cost.stone} камня · ${fmt(cost.seconds)}</button>`}
function renderStructureStatus(){for(let el of document.querySelectorAll('[data-structure-status]')){let b=s.buildings.find(b=>b.id===el.dataset.structureStatus);if(b)el.textContent=buildingCondition(b)}for(let el of document.querySelectorAll('[data-repair]')){let b=s.buildings.find(b=>b.id===el.dataset.repair);if(!b)continue;let cost=C.repairCost(b);el.disabled=!!b.repair||b.hp>=b.maxHp||s.wood<cost.wood||s.stone<cost.stone;el.textContent=(b.ruined?'Восстановить':'Починить')+' · '+cost.wood+' дерева · '+cost.stone+' камня · '+fmt(cost.seconds)}}
function showBag(){openSheet('Всё, что вы добыли','РЮКЗАК',`<div class="inventory">${Object.entries(labels).filter(([k])=>!['vegetables','cookedVegetables'].includes(k)||s[k]>0).map(([k,l])=>`<div>${symbols[k]} ${l}<b>${s[k]}</b></div>`).join('')}<div>🪓 Топор<b>${s.axe===1?'Простой':'Усиленный'}</b></div></div><div class="info-box">Сырые мясо и рыбу нужно жарить на костре: 1 дерево и 20 секунд на порцию. Овощи дают +12 сил, рагу +40. Ягоды дают +15 сил, жареная рыба +30, мясо +35. Рабочие тоже берут готовую еду из этого запаса. Силы также восстанавливаются во время отдыха.</div><button class="secondary" data-do="eat" ${s.cookedMeat+s.cookedFish+s.berries+s.vegetables+s.cookedVegetables===0?'disabled':''}>Поесть и восстановить силы</button><button class="gold wide" data-do="rod" ${s.rod||C.level(s)<1||s.wood<15?'disabled':''}>${s.rod?'✓ Удочка изготовлена':C.level(s)<1?'Удочка · сначала постройте дом':'Изготовить удочку · 15 🪵'}</button><button class="secondary" data-do="axe" ${s.axe>1||C.level(s)<2||s.wood<20||s.stone<15?'disabled':''}>${s.axe>1?'✓ Усиленный топор':C.level(s)<2?'Усиленный топор · нужна мастерская':'Улучшить топор · 20 🪵 15 🪨'}</button><button class="secondary" data-do="improveRod" ${s.rodLevel===2||!s.rod||C.level(s)<2||s.ore<6||s.wood<15?'disabled':''}>${s.rodLevel===2?'✓ Прочная удочка · улов за 6 секунд':'Укрепить удочку · 6 руды + 15 🪵 · нужна мастерская'}</button>`,'bag')}
function showLand(){let cost=20+s.stats.expanded*10;openSheet('Место для будущего','ВАША ЗЕМЛЯ',`<div class="info-box">Домашний участок: <b>${s.claim.w} × ${s.claim.h} клеток</b>.<br>Захвачено участков: <b>${C.territories(s).length-1}</b>.<br>Пунктир на поляне показывает границы. Исследовать можно всю долину, строить — на своей земле. Мосты можно ставить за её границами.</div><p>Победа автоматически присоединяет участок 7 × 7 вокруг базы (у края карты — меньше). На нём можно строить после расчистки, даже без соединения с домом. Повторно покупать эту землю не нужно.</p><p>Платное расширение домашнего участка добавит полосу шириной 2 клетки. Цена следующего расширения: <b>${cost} 🪵</b>.</p><div class="cards">${[['north','↑','На север'],['east','→','На восток · к реке'],['south','↓','На юг'],['west','←','На запад']].map(([d,i,n])=>`<button class="card" data-expand="${d}" ${C.level(s)<1||s.wood<cost?'disabled':''}><span>${i}</span><b>${n}</b><small>${C.level(s)<1?'Сначала завершите дом':cost+' 🪵'}</small></button>`).join('')}</div>`,'land')}
function showBuilding(b){let r=C.recipes[b.type];let kitchen=b.type==='fire'&&C.ready(b)?(b.cooking?'<div class="info-box">Готовится '+(b.cooking.kind==='vegetables'?'рагу':b.cooking.kind==='fish'?'рыба':'мясо')+': '+b.cooking.amount+' порц. · <span data-cook-timer="'+b.id+'">'+fmt(b.cooking.end-s.time)+'</span></div>':'<div class="info-box">1 🪵 и 20 секунд на порцию. Готовка продолжается без вас.</div>'+[['meat','мясо'],['fish','рыбу'],['vegetables','овощи']].filter(([kind])=>kind!=='vegetables'||s.vegetables>0).map(([kind,label])=>'<button class="gold wide" data-cook="'+b.id+'" data-food="'+kind+'" '+(s[kind]<1||s.wood<1?'disabled':'')+'>Пожарить '+label+' · '+Math.min(s[kind],Math.floor(s.wood))+' порц.</button>').join('')):'';openSheet(r.name,b.ruined?'РУИНЫ':b.end?'СТРОИТЕЛЬСТВО':'ВАШЕ ПОСЕЛЕНИЕ','<p>'+r.desc+'</p>'+structurePanel(b)+(b.end?'<div class="info-box">Готово через '+fmt(b.end-s.time)+'</div>':'')+kitchen+militaryPanel(b)+(b.type==='house'&&C.ready(b)?'<button class="gold wide" data-do="workers">Жители · '+s.workers.length+' / '+Workers.capacity(s)+'</button>':'')+'<div class="info-box">Разбор целой постройки вернёт половину материалов. Уборка руин не возвращает материалы здания. Незавершённая готовка возвращается сырыми продуктами.</div><button class="secondary danger" data-remove="'+b.id+'">Снести '+r.name.toLowerCase()+'</button>','building')}
function showSettings(){openSheet('Неспешное приключение','КАК ИГРАТЬ',`<p><b>Движение:</b> нажмите на землю или используйте WASD / стрелки. Персонаж обходит препятствия.</p><p><b>Добыча:</b> нажмите на дерево, камень или овцу, подойдите и нажмите большую кнопку действия.</p><p><b>Стройка:</b> накопите ресурсы, выберите постройку и место внутри своей границы. Постройки можно снести с возвратом половины материалов.</p><p><b>Исследование:</b> на востоке течёт река, в лесу живут овцы и растут ягоды. Сначала постройте дом, затем сделайте удочку. Мясо и рыбу жарьте на костре. Рабочим нужны сон, еда и вода. Рыбак ловит рыбу, повар готовит у костра. За рекой ждут тайник, руда и лагерь разбойников.</p><div class="info-box">Это одиночная версия. Прогресс хранится на устройстве. Строительство и рост ресурсов учитывают до 8 часов отсутствия. Рабочие добывают ресурсы, пока игра открыта. Сетевых боёв пока нет.</div><button class="secondary" data-do="audio">Музыка и звуки</button><button class="secondary danger" data-do="resetPrompt">Начать новую историю</button>`,'settings')}
function showAudio(){openSheet('Долина звучит','МУЗЫКА И ОКРУЖЕНИЕ',`<p>Шаги по траве, удары топора, камень, вода, овцы, стройка и тихая музыка. Звуки создаются прямо в игре.</p><button class="secondary" data-do="toggleAudio">${s.audio.enabled?'Выключить весь звук':'Включить звук'}</button><label class="sound-row">Музыка <input id="musicVolume" aria-label="Громкость музыки" type="range" min="0" max="100" value="${s.audio.music*100}"></label><label class="sound-row">Действия и природа <input id="fxVolume" aria-label="Громкость действий и природы" type="range" min="0" max="100" value="${s.audio.effects*100}"></label>`,'audio')}
function eat(){let result=C.consumeFood(s);if(result.error){toast(result.error);return}audio.play('eat');float('Силы восстановлены');save();renderHUD();if(sheetType==='bag')showBag()}
function startPlacement(type){armyPlacement=false;if(C.level(s)<C.recipes[type].unlock)return;let r=C.recipes[type];if(s.wood<r.wood||s.stone<r.stone){toast('Сначала добудьте ресурсы для этой постройки.');return}closeSheet();route=[];selected=null;placement={type,x:null,y:null};$('#placement').hidden=false;$('.controls').hidden=true;$('#placeName').textContent=r.name;$('#placeHint').textContent=type==='bridge'?'Нажмите на исследованную реку между свободными берегами':'Нажмите на свободное место внутри пунктирной границы';$('#confirmPlace').disabled=true;toast('Размещение: нажмите на свободную клетку')}
function cancelPlacement(){placement=null;$('#placement').hidden=true;$('.controls').hidden=false}
$('#confirmPlace').onclick=()=>{if(!placement||placement.x===null)return;let r=C.startBuild(s,placement.type,placement.x,placement.y);if(r.error){toast(r.error);return}audio.play('place');log(`Начато строительство: ${C.recipes[placement.type].name.toLowerCase()}.`);selected={kind:'building',ref:r.building};cancelPlacement();save();renderHUD();toast('Строительство началось. Можно продолжать исследовать.')};$('#cancelPlace').onclick=cancelPlacement;
$('#sheetBody').onclick=e=>{let b=e.target.closest('button');if(!b||b.disabled)return;if(workerClick(b)||combatClick(b)||militaryClick(b)||economyClick(b))return;if(b.dataset.repair){let result=C.repair(s,b.dataset.repair);economyResult(result);renderHUD();return;}if(b.dataset.worker){if(Workers.assign(s,b.dataset.worker,b.dataset.role)){audio.play('click');save();for(let button of document.querySelectorAll('[data-worker="'+b.dataset.worker+'"]'))button.setAttribute('aria-pressed',String(button.dataset.role===b.dataset.role));renderHUD()}return}if(b.dataset.cook){let result=C.cook(s,b.dataset.cook,b.dataset.food||'meat');if(result.error)toast(result.error);else{audio.play('place');log('На костре готовится еда: '+result.amount+' порц.');save();showBuilding(s.buildings.find(f=>f.id===b.dataset.cook))}return}if(b.dataset.build){startPlacement(b.dataset.build);return}if(b.dataset.expand){let err=C.expand(s,b.dataset.expand);if(err)toast(err);else{audio.play('complete');log('Границы земли расширены. Новые места ждут ваших построек.');save();showLand();toast('Новая земля теперь ваша')}return}if(b.dataset.remove){let id=b.dataset.remove;$('#sheetBody').innerHTML='<p>Снести постройку? Вернётся половина материалов, место станет свободным.</p><button class="gold wide" data-confirm-remove="'+id+'">Да, снести</button>';return}if(b.dataset.confirmRemove){if(C.demolish(s,b.dataset.confirmRemove)){audio.play('destroy');log('Постройка разобрана. Половина материалов возвращена.');selected=null;save();closeSheet();toast('Место освобождено')}else toast(s.buildings.find(b=>b.id===b.dataset.confirmRemove)?.type==='barracks'?'Сначала завершите обучение и обеспечьте отряд местами в других казармах.':s.buildings.find(b=>b.id===b.dataset.confirmRemove)?.type==='pen'?'Сначала выпустите овец из загона.':s.buildings.find(b=>b.id===b.dataset.confirmRemove)?.type==='bridge'?'Сначала освободите мост: на нём кто-то стоит.':'Нельзя снести дом: рабочим не хватит жилья. Сначала постройте другой.');return}switch(b.dataset.do){case'workers':showWorkers();break;case'hire':{let r=Workers.hire(s);if(r.error)toast(r.error);else{audio.play('complete');log(r.worker.name+' присоединился к поселению.');save();showWorkers()}break}case'eat':eat();break;case'rod':if(!s.rod&&C.level(s)>=1&&s.wood>=15){s.wood-=15;s.rod=true;audio.play('complete');log('Вы изготовили удочку. Пора найти реку на востоке.');save();showBag()}break;case'axe':if(s.axe===1&&C.level(s)>=2&&s.wood>=20&&s.stone>=15){s.wood-=20;s.stone-=15;s.axe=2;audio.play('complete');log('Усиленный топор готов. Рубить дерево теперь быстрее.');save();showBag()}break;case'audio':showAudio();break;case'toggleAudio':s.audio.enabled=!s.audio.enabled;audio.start();save();showAudio();break;case'resetPrompt':openSheet('Начать заново?','НОВАЯ ИСТОРИЯ','<p>Текущие постройки, ресурсы и исследования этого устройства будут удалены. Старая версия королевства не затрагивается.</p><button class="secondary danger" data-do="reset">Удалить этот прогресс и начать</button>','reset');break;case'reset':s=C.newGame();battleView=false;armyPlacement=false;workerFocus=null;workerSelection.clear();s.started=true;explored=new Set();route=[];selected=null;task=null;placement=null;cam={x:s.player.x*C.T,y:s.player.y*C.T};reveal();save();closeSheet();renderHUD();toast('Новая история начинается с чистой поляны');break;}};
$('#sheetBody').onchange=workerChange;$('#sheetBody').oninput=e=>{if(e.target.id==='musicVolume')s.audio.music=Number(e.target.value)/100;if(e.target.id==='fxVolume')s.audio.effects=Number(e.target.value)/100;audio.update();save()};$('#closeSheet').onclick=closeSheet;$('#sheetBackdrop').onclick=closeSheet;$('#armyQuick').onclick=toggleArmy;initWarControls();$('#workersMenu').onclick=showWorkers;$('#buildMenu').onclick=showBuild;$('#bagMenu').onclick=showBag;$('#landMenu').onclick=showLand;$('#settings').onclick=showSettings;$('#audio').onclick=()=>{audio.start();showAudio()};$('#act').onclick=beginAction;$('#cancelTask').onclick=()=>{task=null;audio.play('click');renderHUD()};$('#eat').onclick=eat;
$('#home').onclick=()=>{selected=null;let home=s.buildings.find(b=>b.type==='house');if(home)approach({kind:'building',ref:home});else moveTo(10,13);audio.play('click')};
function start(sound){s.started=true;s.audio.enabled=sound;if(sound)audio.start();$('#onboarding').hidden=true;save();toast('Нажмите на дерево, затем «Рубить». Всё начинается с малого.')}
$('#start').onclick=()=>start(true);$('#startSilent').onclick=()=>start(false);
function screenToWorld(e){let r=canvas.getBoundingClientRect();return{x:((e.clientX-r.left)/r.width*view.w+cam.x-view.w/2)/C.T,y:((e.clientY-r.top)/r.height*view.h+cam.y-view.h*.46)/C.T}}
canvas.addEventListener('pointerdown',e=>{if(!s.started||!$('#sheet').hidden)return;if(s.audio.enabled&&!audio.ctx)audio.start();let p=screenToWorld(e),x=Math.floor(p.x),y=Math.floor(p.y);workerFocus=null;if(armyMapClick(x,y))return;if(placement){if(placement.type==='bridge'&&C.water(x,y))x=C.riverX(y);s.explored=[...explored];placement.x=x;placement.y=y;let err=C.placement(s,placement.type,x,y);$('#placeHint').textContent=err||'Свободное место. Подтвердите постройку.';$('#confirmPlace').disabled=!!err;audio.play('click');return}if(!explored.has(`${x},${y}`)){toast('Подойдите ближе, чтобы исследовать этот участок.');return}let n=C.nodeAt(s,x,y),b=C.buildingAt(s,x,y),a=s.sheep.find(a=>a.hp>0&&!a.penTarget&&Math.hypot(a.x+.5-p.x,a.y+.5-p.y)<.8),l=s.landmarks.find(l=>l.x===x&&l.y===y),foundCamp=s.camps.find(c=>!c.defeated&&Math.abs(x-c.x)<=3&&Math.abs(y-c.y)<=3&&Combat.discovered(s,c)),t=foundCamp?{kind:'camp',ref:foundCamp}:l?{kind:'landmark',ref:l}:n?{kind:n.kind,ref:n}:b?{kind:'building',ref:b}:a?{kind:'sheep',ref:a}:C.water(x,y)?{kind:'water',ref:{x,y}}:null;audio.play('click');if(t){if(t.kind==='camp')Combat.select(s,t.ref.id);selected=t;if(!nearTarget(t))approach(t);else route=[]}else{selected=null;moveTo(x,y)}renderHUD()});
document.addEventListener('keydown',e=>{if(!s.started)return;if(e.key==='Escape'){if(armyPlacement||armyAttackMode){quickOrder('cancel');toast('Приказ отменён');return}if(!$('#sheet').hidden)closeSheet();else if(placement)cancelPlacement();else{task=null;route=[]}return}if(!$('#sheet').hidden){if(e.key==='Tab'){let all=[...$('#sheet').querySelectorAll('button:not(:disabled),input')];let first=all[0],last=all.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}return}if(['w','a','s','d','ArrowUp','ArrowLeft','ArrowDown','ArrowRight'].includes(e.key)){e.preventDefault();workerFocus=null;keys.add(e.key);route=[];task=null;selected=null}if(e.code==='Space'&&e.target===document.body){e.preventDefault();beginAction()}});document.addEventListener('keyup',e=>keys.delete(e.key));window.addEventListener('blur',()=>keys.clear());
function resize(){let r=canvas.getBoundingClientRect();view.w=r.width;view.h=r.height;let d=Math.min(2,window.devicePixelRatio||1);canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);ctx.setTransform(d,0,0,d,0,0);ctx.imageSmoothingEnabled=false}window.addEventListener('resize',resize);
function sprite(path,x,y,w,h,frame=null,size=null,flip=false){let im=asset(path);if(!im.complete||!im.naturalWidth)return;ctx.save();if(flip){ctx.translate(x+w,y);ctx.scale(-1,1);x=0;y=0}if(frame!==null){let sw=typeof size==='object'?size.w:(size||im.height),sh=typeof size==='object'?size.h:(size||im.height),frames=Math.max(1,Math.floor(im.width/sw));ctx.drawImage(im,Math.floor(frame%frames)*sw,0,sw,sh,x,y,w,h)}else ctx.drawImage(im,x,y,w,h);ctx.restore()}
function shadow(x,y,w){}
function terrainCell(sx,sy,x,y,w=C.T,h=C.T){let im=asset('Terrain/Tileset/Tilemap_color1.png');if(im.complete&&im.naturalWidth)ctx.drawImage(im,sx,sy,64,64,x,y,w,h)}
function drawBuilding(b){let r=C.recipes[b.type],x=b.x*C.T,y=b.y*C.T,w=r.w*C.T;C.buildingState(b);if(b.ruined){drawRuins(b);drawStructureDamage(b);return}ctx.save();if(b.end)ctx.globalAlpha=.45;
 if(b.type==='house')sprite('Buildings/Blue Buildings/House1.png',x-10,y-45,w+20,(w+20)*1.5);
 else if(b.type==='barracks')sprite('Buildings/Blue Buildings/Barracks.png',x-20,y-35,w+40,171);
 else if(b.type==='workshop')drawWorkshop(x,y,w,r.h*C.T);
 else if(b.type==='tower')sprite('Buildings/Blue Buildings/Tower.png',x-20,y-75,88,176);
 else if(b.type==='fire')drawCampfire(b);
 else if(b.type==='bridge'){for(let i=0;i<3;i++)terrainCell(384,192,x+i*C.T,y);}
 else if(b.type==='well'){sprite('Terrain/Tileset/Water Background color.png',x+8,y+12,32,26);for(let [dx,dy]of [[-3,0],[23,0],[-3,22],[23,22]])sprite(ROCK,x+dx,y+dy,28,28)}
 else if(b.type==='fence'||b.type==='gate'){for(let dx of b.type==='fence'?[0,14,28]:[0,32])sprite(STUMP,x+dx-8,y-15,32,43)}
 else if(b.type==='lantern'){sprite(STUMP,x+2,y-9,44,59);sprite('Particle FX/Fire_03.png',x,y-28,48,48,anim*8,64)}
 ctx.restore();drawStructureDamage(b);if(b.end){ctx.fillStyle='#fff1c7';ctx.font='11px system-ui';ctx.textAlign='center';ctx.fillText(fmt(b.end-s.time),x+w/2,y+r.h*C.T+10)}}
function draw(){ctx.clearRect(0,0,view.w,view.h);ctx.fillStyle='#274635';ctx.fillRect(0,0,view.w,view.h);ctx.save();ctx.translate(Math.round(view.w/2-cam.x),Math.round(view.h*.46-cam.y));let x0=Math.max(0,Math.floor((cam.x-view.w/2)/C.T)-1),y0=Math.max(0,Math.floor((cam.y-view.h*.46)/C.T)-2),x1=Math.min(C.W,Math.ceil((cam.x+view.w/2)/C.T)+1),y1=Math.min(C.H,Math.ceil((cam.y+view.h*.54)/C.T)+2),tile=asset('Terrain/Tileset/Tilemap_color1.png');
for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){let px=x*C.T,py=y*C.T;if(C.water(x,y)){sprite('Terrain/Tileset/Water Background color.png',px,py,C.T,C.T);}else terrainCell(64,64,px,py)}
let c=s.claim;ctx.strokeStyle='#f5e9b49a';ctx.lineWidth=1.5;ctx.setLineDash([5,7]);for(let land of C.territories(s))ctx.strokeRect(land.x*C.T,land.y*C.T,land.w*C.T,land.h*C.T);ctx.setLineDash([]);
if(route.length){let dest=route.at(-1);ctx.strokeStyle='#fff0ba88';ctx.setLineDash([2,6]);ctx.beginPath();ctx.moveTo(s.player.x*C.T,s.player.y*C.T);for(let p of route)ctx.lineTo(p.x*C.T,p.y*C.T);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle='#fff0ba';ctx.beginPath();ctx.ellipse(dest.x*C.T,dest.y*C.T,11,5,0,0,7);ctx.stroke()}
for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++)if(!explored.has(`${x},${y}`)){ctx.fillStyle='#243d32';ctx.fillRect(x*C.T,y*C.T,C.T+1,C.T+1);}
let objects=[];for(let n of s.nodes)if(n.x>=x0-1&&n.x<x1+1&&n.y>=y0-1&&n.y<y1+2&&explored.has(`${n.x},${n.y}`))objects.push({y:n.y+1,draw:()=>{let x=(n.x+.5)*C.T,y=(n.y+.7)*C.T;if(n.hp<=0){if(n.kind==='tree')sprite(STUMP,x-36,y-57,72,96);return}if(n.kind==='tree'){shadow(x,y,22);let shake=task?.target===n?Math.sin(anim*30)*2:0;sprite(TREE,x-43.5+shake,y-99,87,116,0,{w:192,h:256})}else if(n.kind==='rock'){shadow(x,y,15);sprite(ROCK,x-23,y-34,46,46)}else{sprite('Terrain/Decorations/Bushes/Bushe1.png',x-26,y-36,52,52)}if(selected?.ref===n){ctx.strokeStyle='#ffedb0';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(x,y+2,23,8,0,0,7);ctx.stroke()}}});
for(let camp of s.camps)if(!camp.defeated&&explored.has(camp.x+','+camp.y))for(let b of camp.structures||[])objects.push({y:b.y+C.recipes[b.type].h-.2,draw:()=>drawEnemyBuilding(camp,b)});for(let e of Combat.enemies(s))if(explored.has(Math.floor(e.x)+','+Math.floor(e.y)))objects.push({y:e.y,draw:()=>drawEnemy(e)});for(let l of s.landmarks)if(explored.has(l.x+','+l.y))objects.push({y:l.y+.8,draw:()=>drawLandmark(l)});for(let b of s.buildings)objects.push({y:b.type==='bridge'?-1:b.y+C.recipes[b.type].h-.2,draw:()=>drawBuilding(b)});
for(let a of s.sheep)if(a.hp>0&&explored.has(`${Math.floor(a.x)},${Math.floor(a.y)}`))objects.push({y:a.y+1,draw:()=>{let x=(a.x+.5)*C.T,y=(a.y+.7)*C.T;shadow(x,y,14);sprite(SHEEP+(a.moving?'Sheep_Move.png':'Sheep_Idle.png'),x-40,y-56,80,80,anim*(a.moving?7:4),128);if(selected?.ref===a){ctx.strokeStyle='#ffedb0';ctx.beginPath();ctx.ellipse(x,y,20,7,0,0,7);ctx.stroke()}}});
for(let w of s.workers)objects.push({y:w.y,draw:()=>{let x=w.x*C.T,y=w.y*C.T,sleep=w.need==='sleep'&&!w.moving&&w.needPlanned,working=!w.moving&&w.target&&!w.need&&!w.fireJob;shadow(x,y+4,11);let tool=w.role==='wood'?'Axe':w.role==='stone'?'Pickaxe':w.role==='cook'?'Knife':'Hammer',name=w.moving?'Pawn_Run':working&&w.role!=='fish'?'Pawn_Interact '+tool:'Pawn_Idle';if(sleep){ctx.save();ctx.translate(x,y);ctx.rotate(-Math.PI/2);sprite(P+'Pawn_Idle.png',-44,-44,88,88,0,192);ctx.restore()}else sprite(P+name+'.png',x-44,y-60,88,88,anim*(w.moving||working?8:4),192,w.face<0);ctx.fillStyle='#f4dfaa';ctx.font='bold 8px system-ui';ctx.textAlign='center';ctx.fillText(sleep?'z Z':w.name,x,y-(sleep?20:29));if(working&&w.role==='fish')sprite('Particle FX/Water Splash.png',(w.fishSpot.x-.5)*C.T,(w.fishSpot.y-.5)*C.T,96,96,anim*6,192);if(w.splash?.end>s.time)sprite('Particle FX/Water Splash.png',(w.splash.x-1)*C.T,(w.splash.y-1)*C.T,96,96,(s.time-w.splash.start)*7,192);if(w.thirst<25||w.hunger<25){ctx.font='12px system-ui';ctx.fillText(w.thirst<25?'Вода':'Еда',x,y-40)}}});
for(let u of s.soldiers)objects.push({y:u.y,draw:()=>drawSoldier(u)});objects.push({y:s.player.y,draw:()=>{let x=s.player.x*C.T,y=s.player.y*C.T;shadow(x,y+4,12);let name=task?task.kind==='tree'?'Pawn_Interact Axe':task.kind==='rock'||task.kind==='ore'?'Pawn_Interact Pickaxe':task.kind==='sheep'?'Pawn_Interact Knife':'Pawn_Idle':moving?'Pawn_Run':'Pawn_Idle';sprite(P+name+'.png',x-48,y-64,96,96,anim*(task?9:moving?9:5),192,face<0);if(task?.kind==='water'){let target=targetPoint({kind:'water',ref:task.target});sprite('Particle FX/Water Splash.png',(target.x-1)*C.T,(target.y-1)*C.T,96,96,anim*6,192)}}});objects.sort((a,b)=>a.y-b.y);for(let o of objects)o.draw();drawArrows();
for(let p of particles){ctx.globalAlpha=Math.min(1,p.life);sprite('Particle FX/Dust_01.png',p.x-16,p.y-16,32,32,(1-p.life)*8,64)}ctx.globalAlpha=1;
if(placement){let r=C.recipes[placement.type];for(let land of C.territories(s))for(let y=land.y;y<land.y+land.h;y++)for(let x=land.x;x<land.x+land.w;x++){ctx.strokeStyle='#f4ecc135';ctx.strokeRect(x*C.T,y*C.T,C.T,C.T)}if(placement.x!==null){let err=C.placement(s,placement.type,placement.x,placement.y);ctx.fillStyle=err?'#e26f6a77':'#cae3a077';ctx.fillRect(placement.x*C.T,placement.y*C.T,r.w*C.T,r.h*C.T);ctx.strokeStyle=err?'#f8a196':'#f4f1b3';ctx.lineWidth=2;ctx.strokeRect(placement.x*C.T,placement.y*C.T,r.w*C.T,r.h*C.T)}}
ctx.restore();
drawNight()}

function update(dt){if(!s.started)return;s.time+=dt;let modal=!$('#sheet').hidden;moving=false;if(!modal&&!placement){let dx=(keys.has('d')||keys.has('ArrowRight')?1:0)-(keys.has('a')||keys.has('ArrowLeft')?1:0),dy=(keys.has('s')||keys.has('ArrowDown')?1:0)-(keys.has('w')||keys.has('ArrowUp')?1:0);if(dx||dy){let len=Math.hypot(dx,dy),nx=s.player.x+dx/len*2.6*dt,ny=s.player.y+dy/len*2.6*dt;if(C.walkable(s,Math.floor(nx),Math.floor(s.player.y)))s.player.x=nx;if(C.walkable(s,Math.floor(s.player.x),Math.floor(ny)))s.player.y=ny;moving=true;if(dx)face=dx>0?1:-1}else if(route.length){let p=route[0],d=dist(s.player,p);if(!C.walkable(s,Math.floor(p.x),Math.floor(p.y))){route=[]}else if(d<2.6*dt){s.player.x=p.x;s.player.y=p.y;route.shift()}else{s.player.x+=(p.x-s.player.x)/d*2.6*dt;s.player.y+=(p.y-s.player.y)/d*2.6*dt;if(Math.abs(p.x-s.player.x)>.05)face=p.x>s.player.x?1:-1}moving=true}}
if(moving){stepClock+=dt;if(stepClock>.32){audio.play('step');stepClock=0}reveal()}if(task){let duration=task.end-task.start;let beats=Math.floor((s.time-task.start)/.85);if(beats>task.hits&&s.time<task.end&&task.kind!=='water'){task.hits=beats;audio.play(task.kind==='tree'?'chop':task.kind==='rock'||task.kind==='ore'?'rock':task.kind==='sheep'?'hunt':'collect');addParticles(task.target.x+.5,task.target.y+.5,task.kind==='tree'?'#d7b978':'#d3d4bc',3)}if(s.time>=task.end)completeTask()}else if(!moving){let fire=s.buildings.some(b=>(b.type==='fire'&&C.ready(b)||b.burningUntil>s.time)&&dist(s.player,{x:b.x+.5,y:b.y+.5})<3);s.energy=Math.min(100,s.energy+dt*(fire?1.6:.35))}
for(let a of s.sheep){a.moving=false;if(a.hp<=0||a.penTarget||task?.target===a||selected?.ref===a)continue;let phase=Math.sin(s.time*.23+Number(a.id.slice(1))*2);if(phase>.6){let nx=a.x+Math.cos(s.time*.11+Number(a.id.slice(1)))*dt*.15,ny=a.y+Math.sin(s.time*.11+Number(a.id.slice(1)))*dt*.15;if(C.walkable(s,Math.floor(nx),Math.floor(ny))&&Math.hypot(nx-a.homeX,ny-a.homeY)<2){a.x=nx;a.y=ny;a.moving=true}}}
s.explored=[...explored];for(let event of Military.tick(s,dt)){if(event.message){if(event.territory)reveal();toast(event.message);save()}if(event.global||dist(s.player,event)<7){audio.play(event.kind);if(event.damage)addParticles(event.x,event.y,'#efc17f',3)}}for(let u of s.soldiers)if(u.hp>0)for(let dy=-3;dy<=3;dy++)for(let dx=-3;dx<=3;dx++)if(dx*dx+dy*dy<10)explored.add(Math.floor(u.x+dx)+','+Math.floor(u.y+dy));for(let event of Economy.tick(s,dt)){if(event.message)toast(event.message);if(dist(s.player,event)<7)audio.play(event.kind)}for(let event of Workers.tick(s,dt)){if(dist(s.player,event)<7){audio.play(event.kind);if(event.resource)addParticles(event.x,event.y,event.resource==='wood'?'#d7b978':'#bfc8b7',3)}}let done=C.finishBuildings(s);for(let b of done){log(`${C.recipes[b.type].name} готов${b.type==='house'?'':'а'}. Поселение растёт.`);audio.play('complete');toast(`${C.recipes[b.type].name}: строительство завершено`);reveal();save()}for(let amount of C.finishCooking(s)){audio.play('complete');toast('Еда готова: '+amount+' порц. в рюкзаке');log('Приготовлено еды: '+amount+' порц.');save()}C.regrow(s);if(Math.floor(s.time)%3===0&&s.buildings.some(b=>b.end&&dist(s.player,{x:b.x,y:b.y})<4)&&Math.floor((s.time-dt)/3)!==Math.floor(s.time/3))audio.play('hammer');for(let p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=80*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);let focusWorker=s.workers.find(w=>w.id===workerFocus);cam.x+=((focusWorker?focusWorker.x:battleView?s.camp.x+.5:s.player.x)*C.T-cam.x)*Math.min(1,dt*8);cam.y+=((focusWorker?focusWorker.y:battleView?s.camp.y+.5:s.player.y)*C.T-cam.y)*Math.min(1,dt*8);uiClock+=dt;saveClock+=dt;if(uiClock>.12){renderHUD();uiClock=0}if(saveClock>5){save();saveClock=0}}
function offline(){Combat.suspend(s);let dt=Math.min(28800,Math.max(0,(Date.now()-s.last)/1000));if(s.started){s.time+=dt;for(let e of C.tickStructures(s,dt,true))log(e.message);s.energy=Math.min(100,s.energy+dt*.35);Workers.rest(s,dt);C.finishBuildings(s).forEach(b=>log(`${C.recipes[b.type].name}: строительство завершилось, пока вас не было.`));Economy.tick(s,0);Military.finish(s);C.finishCooking(s).forEach(amount=>log('За время вашего отсутствия приготовлено еды: '+amount+' порц.'));C.regrow(s)}s.last=Date.now()}
function frame(now){let dt=Math.min(.1,(now-last)/1000);last=now;if(!document.hidden){anim+=dt;update(dt);draw()}requestAnimationFrame(frame)}
document.addEventListener('visibilitychange',()=>{keys.clear();route=[];task=null;if(document.hidden)save();else{offline();last=performance.now();renderHUD()}audio.update()});window.addEventListener('pagehide',save);
if(window.Telegram?.WebApp?.initData){window.Telegram.WebApp.ready();window.Telegram.WebApp.expand()}
offline();reveal();resize();renderHUD();$('#onboarding').hidden=s.started;if(s.started){$('#audio').textContent='♫';toast('С возвращением. Нажмите на карту, чтобы включить звуки.')}requestAnimationFrame(frame);





